edits.after:
  constructor(element?: string | Element | null, config?: Partial<DrawerConfig> | null) {
  super(element, config)
  this._swipeHelper = null
  this._resizeObserver = null
  this._resizeFrame = null
  EventHandler.on(this._element, this.constructor.eventName('shown'), () => {
    const focusable = this._element.querySelector('[autofocus], button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
    if (focusable) {
      focusable.focus();
    }
  });
  this._initResizeObserver()
}
